"""Portable scene dashboard with review tiers, AI-only proxy and hash-bound human geometry editor."""
import argparse
import base64
import html
import json
from pathlib import Path
import subprocess
from evaluate_clip_proxy import evaluate
from compare_review_probes import compare


def data(path, mime):return 'data:'+mime+';base64,'+base64.b64encode(Path(path).read_bytes()).decode()
def esc(value):return html.escape(str(value))
LABELS={'shot_direction_review':'Şuta yönelmiş hızlı ayrılma — kale geçişi gözlenmedi','release_recontrol_review':'Ayrılma / yeniden kontrol — şut kanıtı eksik','shot_candidate':'Şut adayı','goal_entry_candidate':'Kale bölgesi adayı','endline_crossing':'Çizgi geçiş adayı','fast_release_review':'Hızlı ayrılma — kale bağlamı yok','control_change_unknown_team':'Kontrol değişimi — takım bilinmiyor','completed_pass_candidate':'Tamamlanan pas adayı','ball_recovery_candidate':'Top kazanma adayı'}


def export(root,output):
    root=Path(root);proxy=evaluate(root);panels=[];table=[]
    probe_html=''.join(f'<div><img src="{data(p["image"],"image/png")}" alt="AI inceleme örneği"><p>{esc(p["scene"])} / kare {p["frame"]}: {esc(p["note"])}. 5 px yakınında eski seçim: {int(p["v052_selected"]["within_tolerance"])}; yeni hipotez: {int(p["v06_hypotheses"]["within_tolerance"])}.</p></div>' for p in compare(root))
    for i,r in enumerate(proxy['rows']):
        name=r['scene'];p=root/name;s=json.loads((p/'summary.json').read_text());events=json.loads((p/'events.json').read_text())
        baseline=Path('results/full_analysis_v052_release')/name
        web=p/'web.mp4'
        if not web.exists():subprocess.run(['ffmpeg','-y','-loglevel','error','-i',str(p/'analysis.mp4'),'-c:v','libx264','-pix_fmt','yuv420p','-movflags','+faststart','-an',str(web)],check=True)
        old=json.loads((baseline/'summary.json').read_text());geo=json.loads((baseline/'geometry.json').read_text())
        proposals=json.dumps(dict(goals=geo.get('automatic_goal_candidates',[]),endlines=geo.get('automatic_endline_candidates',[]))).replace('<','\\u003c')
        current=r['current'];before=r['baseline']
        table.append(f'<tr><td><a href="#scene-{i}">{i+1}</a></td><td>{r["anchor_s"]:.2f} s</td><td>{int(before["ai_window_hit"])}</td><td>{int(current["ai_window_hit"])}</td><td>{current["candidates_per_minute"]:.1f}</td><td>{current["unmatched_review_candidates_per_minute"]:.1f}</td><td>—</td></tr>')
        timeline=''.join(f'<a class="seek" href="#video-{i}" data-time="{e["time_s"]}">{e["time_s"]:.2f} s · {esc(LABELS[e["type"]])} · {e["tier"]}</a><small>{esc(" · ".join(e["reasons"]))}</small>' for e in events) or '<p>Aday çıkmadı. Olay olmadığı anlamına gelmez.</p>'
        counts=''.join(f'<tr><td>{esc(label)}</td><td>{sum(e["type"]==kind and e["tier"]=="A" for e in events)}</td><td>{sum(e["type"]==kind and e["tier"]=="B" for e in events)}</td><td>—</td></tr>' for kind,label in LABELS.items())
        background=Path('results/measured')/name/'pitch_context/scene_000_background.png'
        panels.append(f'''<section id="scene-{i}"><h2>Kesit {i+1} · {s['duration_s']:.1f} s</h2><div class="columns"><div><video id="video-{i}" playsinline controls preload="none" src="{data(web,'video/mp4')}"></video><p>Sarı: alternatif top hipotezleri; aynı karede birden fazla olabilir. Yeşil: kişi. Geometri: {esc(s['geometry_source'])}. Bunlar gerçek top/olay onayı değildir.</p><a href="#heat-{i}">Isı haritasına git</a> · <a href="#scene-{(i+1)%9}">Sonraki kesit</a> · <a href="#contents">Kesitler</a><h3 id="heat-{i}">Şematik saha yoğunluğu</h3><img class="heatmap" src="{data(baseline/'schematic_heatmap.png','image/png')}" alt="Kesit {i+1} göreli kişi yoğunluğu"><p>v0.5.2 ile aynı kişi gözlemleri. Görünen alanın yaklaşık normalizasyonu; 45 × 25 m yalnız çizim şablonu. Gerçek saha konumu, koşu mesafesi veya metre kalibrasyonu değildir. Renk ölçeği kesite özeldir.</p><details><summary>Geometriyi çiz / otomatik öneriyi düzelt</summary><article class="geometry-editor" data-scene="{name}" data-hash="{s['video_sha256']}"><p>Kale: sırayla sol direk ayağı → sol üst → sağ üst → sağ direk ayağı. Çizgi: iki uç. Noktaları sürükleyebilirsin; görünmeyen direği tahminle tamamlama.</p><canvas width="640" height="360" data-image="{data(background,'image/png')}"></canvas><select class="kind" aria-label="Çizim türü"><option value="goal">Kale ağzı — 4 nokta</option><option value="endline">Aut çizgisi — 2 nokta</option></select><button class="proposal">Otomatik öneriyi taslağa yükle</button><button class="undo">Geri al</button><button class="clear">Temizle</button><p><label>İnceleyen <input class="reviewer" autocomplete="name"></label></p><label><input type="checkbox" class="confirmed"> Çizimi görüntüden kontrol ettim</label><p><button class="download">İnsan geometri kaydını indir</button></p><p class="geometry-status" role="status" aria-live="polite">JavaScript açıkken çizim yapılabilir.</p><script type="application/json" class="geometry-proposals">{proposals}</script></article><p>İndirilen {name}.json dosyasını aynı geometri klasörüne koy. Çıkarım <code>--geometry-dir KLASÖR</code> ile hash ve insan onayını doğrular. Dosya indirmek mevcut ölçümleri değiştirmez. Otomatik öneriler açık onay olmadan kullanılmaz.</p></details></div><aside><h3>Kanıt kademeleri</h3><p>A: daha güçlü kural kanıtı; B: düşük kanıt, inceleme gerekli. İkisi de onaysız adaydır.</p><table><tr><th>Aday türü</th><th>A</th><th>B</th><th>İnsan onayı</th></tr>{counts}</table><h3>AI zaman penceresi</h3><p>{r['uncertainty_s'][0]:.2f}–{r['uncertainty_s'][1]:.2f} s. {esc(r['notes'])}</p><p>±2 s eşleşme: eski {int(before['ai_window_hit'])} → yeni {int(current['ai_window_hit'])}. Aynı anda yanlış nesne izlenmiş olabilir; doğruluk metriği değil.</p><p>Aday yükü {current['candidates_per_minute']:.1f}/dk; eşleşmeyen inceleme yükü {current['unmatched_review_candidates_per_minute']:.1f}/dk. Gerçek yanlış aday/dk: bilinmiyor.</p><details><summary>İşlemsel sayaçlar ve belirsizlikler</summary><p>{len(s['unevaluable_frames'])} referans uyumsuzluğu karesi · {s['hypothesis_observations']} alternatif gözlem satırı · {s['frames_with_hypotheses']} hipotezli kare. Eski tek seçim: {old['selected_ball_frames']} kare. Farklı çıktı türleri; sayılar accuracy/recall değildir.</p><pre>{esc(json.dumps(s['diagnostics'],ensure_ascii=False,indent=2))}</pre></details><details><summary>Olay adaylarına git ({len(events)})</summary>{timeline}</details></aside></div></section>''')
    nav=''.join(f'<a href="#scene-{i}">Kesit {i+1}</a>' for i in range(9))
    script=Path('geometry_sketch.js').read_text()+'''\nfor(const section of document.querySelectorAll('section'))for(const link of section.querySelectorAll('.seek'))link.addEventListener('click',()=>{const v=section.querySelector('video'),t=Number(link.dataset.time);if(v.readyState>=1)v.currentTime=t;else{v.addEventListener('loadedmetadata',()=>v.currentTime=t,{once:true});v.load()}});'''
    content=f'''<!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Halı Saha v0.6 · İnceleme</title><style>body{{margin:0;background:#101d28;color:#e5f1f5;font:16px system-ui}}main{{max-width:1400px;margin:auto;padding:18px}}header,aside,details{{background:#1b3343;padding:18px;border-radius:12px;margin:12px 0}}.columns{{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(300px,1fr);gap:22px}}video,img,canvas{{width:100%;max-width:100%;border-radius:8px}}canvas{{touch-action:none}}a{{color:#9cddff}}nav{{display:flex;flex-wrap:wrap;gap:8px}}nav a,button,.seek{{display:inline-block;padding:12px;background:#28566b;border:0;border-radius:6px;color:white;margin:4px 0}}.seek{{display:block}}input,select,button{{font:inherit}}input:not([type=checkbox]){{max-width:180px}}table{{width:100%;border-collapse:collapse}}th,td{{padding:9px;border-bottom:1px solid #47606e;text-align:left}}.scroll{{overflow:auto}}p{{line-height:1.5}}section{{border-top:2px solid #426477;padding-top:14px;margin-top:32px}}pre{{white-space:pre-wrap}}.geometry-status{{background:#493e24;padding:12px}}small{{color:#b0cbd7}}@media(max-width:850px){{.columns{{grid-template-columns:1fr}}main{{padding:10px}}th,td{{padding:6px}}}}</style><main><header><h1>Halı Saha · v0.6 inceleme</h1><p>Ölçülen: aday yükü, AI zaman eşleşmesi, kişi yoğunluğu. İnsan doğruluğu henüz ölçülmedi.</p><strong>AI pencere eşleşmesi {proxy['baseline_hits']}/9 → {proxy['current_hits']}/9 · İnsan etiketi: 0</strong><p>Şut, pas, gol veya oyuncu reytingi onaylanmış toplamlar değildir. Aday artışı tek başına iyileşme kanıtı sayılmaz. Eşik değerleri configs/review_v06.json içinde (v0.6.1 mantık düzeltmesinde sayısal eşikler değişmedi); model yeniden çalıştırılmadı.</p></header><nav id="contents">{nav}</nav><h2>AI ve insan sonuçları ayrı</h2><div class="scroll"><table><tr><th>Kesit</th><th>AI zaman</th><th>Eski eşleşme</th><th>Yeni eşleşme</th><th>Aday/dk</th><th>Eşleşmeyen/dk</th><th>İnsan P/R</th></tr>{''.join(table)}</table></div><p>Zaman eşleşmesi; şut, kale bölgesi veya çizgi geçişi adayının AI zamanının ±2 saniyesinde bulunmasıdır. Hızlı ayrılma tek başına bu hesaba girmez. Eşleşmeyen aday yanlış olay demek değildir. Tolerans, eşikler ve AI etiketleri JSON raporunda ayrı kayıtlıdır.</p><details><summary>Seçilmiş AI top / vücut örnekleri — başarılar ve kalan hatalar</summary><p>Sarı çember AI inceleme noktasıdır. Beş elle seçilmiş örnek; insan etiketi veya doğruluk oranı değildir.</p><div class="columns">{probe_html}</div></details>{''.join(panels)}<footer><p>İnsan top etiketleme pilotu: results/human_pilot_v06. Görünür/görünmez top ve rastgele olay pencereleri hazır; human sonuçları evaluate_review.py ile hesaplanır. Geometri girdisi ayrıca yukarıdan indirilebilir. AI geometri kullanımı bu koşuda açıkça seçilmiştir; varsayılan çıkarımda kapalıdır.</p></footer></main><script>{script}</script></html>'''
    Path(output).write_text(content,encoding='utf-8')
    Path(output).with_suffix('.json').write_text(json.dumps(proxy,indent=2,ensure_ascii=False))

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',default='results/review_v06_final');p.add_argument('--output',default='results/halisaha-analiz-v060.html');a=p.parse_args();export(a.root,a.output)
